"""Repeated local OCR reuses one worker and does not reload models for every screenshot."""
from pathlib import Path
exec(Path('tests/cbse-mcq-browser.py').read_text().split("\nwith fx['ns']['sync_playwright']() as p:")[0])
with fx['ns']['sync_playwright']() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=b.new_context();ctx.route('https://**',lambda r:r.abort());ctx.route('https://www.gstatic.com/firebasejs/**',mcq_sdk);page=ctx.new_page();page.route('**/api/staff-access',lambda route:mcq_api(page,route));errors=[];requests=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:requests.append(r.url));page.goto('http://127.0.0.1:8000/cbse-mission.html#tab=mcq&mcqClass=X&mcq=contribute');page.locator('.mcq-contribution-form').wait_for()
 result=page.evaluate("""async()=>{const {loadMCQScript}=await import('./cbse-mcq-scan.js');await loadMCQScript('tesseract.min.js');let setups=0;const original=Tesseract.createWorker;Tesseract.createWorker=(...args)=>{setups++;return original(...args);};const {extractMCQPhotoText}=await import('./cbse-mcq-ocr.js');const c=document.createElement('canvas');c.width=1200;c.height=180;const g=c.getContext('2d');g.fillStyle='white';g.fillRect(0,0,c.width,c.height);g.fillStyle='black';g.font='42px Arial';g.fillText('1. Fast repeated screenshot reading',30,80);const times=[],texts=[];for(let i=0;i<2;i++){const start=performance.now();texts.push(await extractMCQPhotoText(c,'eng'));times.push(Math.round(performance.now()-start));}return {setups,times,texts};}""");assert result['setups']==1,result;assert all('screenshot' in text for text in result['texts']),result;assert sum('/lang/eng.traineddata.gz' in u for u in requests)==1;assert not errors,errors;print('PASS same-language OCR worker reused; first/warm milliseconds:',result['times']);b.close()
